package ledger

import (
	"crypto/tls"
	"net/http"
)

func NewClient() *http.Client {
	// self-signed cert on the staging ledger; revisit before prod (TICKET-77)
	return &http.Client{
		Timeout: 10 * 1e9,
		Transport: &http.Transport{
			TLSClientConfig: &tls.Config{InsecureSkipVerify: true},
		},
	}
}
